package com.eldenworld.core.balance;
import com.eldenworld.core.EldenWorldCore; import com.eldenworld.core.requirements.RequirementChecker; import net.minecraft.resources.ResourceLocation; import net.minecraft.server.level.ServerLevel; import net.minecraft.server.level.ServerPlayer; import net.minecraft.world.entity.LivingEntity; import net.minecraft.world.entity.ai.attributes.*; import net.minecraft.world.entity.monster.Monster; import net.minecraftforge.event.entity.EntityJoinLevelEvent; import net.minecraftforge.eventbus.api.SubscribeEvent; import net.minecraftforge.fml.common.Mod; import net.minecraftforge.registries.ForgeRegistries; import java.util.*;
@Mod.EventBusSubscriber(modid=EldenWorldCore.MOD_ID) public final class WorldScalingEvents {static final UUID H=UUID.fromString("d39cbdd2-54f4-4f62-ae92-c99b57ea1f50"),D=UUID.fromString("fb80b080-c08c-4a8d-b105-3319d2f5e02a"),A=UUID.fromString("a6d87c9e-3490-4370-a9a7-fef9180e0cb3"); private WorldScalingEvents(){}
@SubscribeEvent public static void join(EntityJoinLevelEvent e){if(!(e.getLevel() instanceof ServerLevel l)||!(e.getEntity() instanceof Monster m)||m.isNoAi())return;List<ServerPlayer> ps=l.getEntitiesOfClass(ServerPlayer.class,m.getBoundingBox().inflate(64));if(ps.isEmpty())return;int s=0,c=0;for(ServerPlayer p:ps)try{s+=Math.min(100,RequirementChecker.pstLevel(p));c++;}catch(RuntimeException ignored){}if(c==0)return;double pr=(s/(double)c)/100;if(pr<=.05)return;Tier t=tier(m,m.getMaxHealth());mul(m.getAttribute(Attributes.MAX_HEALTH),H,"EldenWorld M5 world HP",pr*t.hp);mul(m.getAttribute(Attributes.ATTACK_DAMAGE),D,"EldenWorld M5 world damage",pr*t.damage);add(m.getAttribute(Attributes.ARMOR),A,"EldenWorld M5 world armor",pr*t.armor);m.setHealth(m.getMaxHealth());}
static Tier tier(LivingEntity m,double hp){ResourceLocation id=ForgeRegistries.ENTITY_TYPES.getKey(m.getType());String ns=id==null?"":id.getNamespace(),p=id==null?"":id.getPath();boolean bn=p.contains("boss")||p.contains("leviathan")||p.contains("ignis")||p.contains("harbinger")||p.contains("dragon"),bm=ns.contains("cataclysm")||ns.contains("mowzie")||ns.contains("aquamirae");if(hp>=180||bn||(bm&&hp>=100))return new Tier(.12,.07,2);if(hp>=60)return new Tier(.24,.12,3);return new Tier(.38,.18,4);}static void mul(AttributeInstance a,UUID id,String n,double x){if(a!=null&&a.getModifier(id)==null&&x>0)a.addPermanentModifier(new AttributeModifier(id,n,x,AttributeModifier.Operation.MULTIPLY_BASE));}static void add(AttributeInstance a,UUID id,String n,double x){if(a!=null&&a.getModifier(id)==null&&x>0)a.addPermanentModifier(new AttributeModifier(id,n,x,AttributeModifier.Operation.ADDITION));}record Tier(double hp,double damage,double armor){}}
